(function auditPytestFileProgress(log,index,plannedNodes,status,H){
const need=(ok,msg)=>{if(!ok)throw Error(msg+" (shard"+index+")");};
const lines=log.replace(/\x1b\[[0-9;]*m/g,"").split(/\r?\n/).map(raw=>{
 if(raw.startsWith("\ufeff")){need(/^\ufeff\d{4}-\d\d-\d\dT/.test(raw),"BOM outside timestamp envelope");raw=raw.slice(1);}
 return raw.replace(/^\d{4}-\d\d-\d\dT[0-9:.]+Z /,"");
});
need(lines.some(l=>/^platform linux -- Python 3\.12\.13, pytest-9\.0\.3, pluggy-1\.6\.0$/.test(l)),"Actual pytest version");
const collection=[];for(let i=0;i<lines.length;i++)if(/^collected \d+ items$/.test(lines[i]))collection.push(i);
need(collection.length===1,"Unique collected count");const first=collection[0];
need(Number(lines[first].match(/\d+/)[0])===plannedNodes.length,"Exact plan collection count");
const expected=[];for(const node of plannedNodes){const path=node.split("::")[0];if(!expected.length||expected[expected.length-1].path!==path)expected.push({path,nodes:[]});expected[expected.length-1].nodes.push(node);}
const groups=[],observations=[];let markers=0,ended=false;
for(let i=first+1;i<lines.length;i++){
 const line=lines[i];if(/^={5,}/.test(line)){ended=true;break;}if(!line.trim())continue;
 const header=line.match(/^(tests\/\S+\.py)\s+([.FsxXE]*)(?:\s+\[\s*(\d{1,3})%\])?\s*$/);
 let letters,percentage;
 if(header){const path=header[1];need(groups.length<expected.length&&expected[groups.length].path===path,"Ordered exact file header");groups.push({path,markers:"",lines:[]});letters=header[2];percentage=header[3];}
 else {const continuation=line.match(/^([.FsxXE]*)(?:\s+\[\s*(\d{1,3})%\])?\s*$/);need(!!continuation&&groups.length>0,"Unambiguous continuation line");letters=continuation[1];percentage=continuation[2];need(letters.length>0||percentage!==undefined,"Nonempty progress observation");}
 const group=groups[groups.length-1];group.markers+=letters;group.lines.push({line_number:i+1,text:line});
 markers+=letters.length;need(markers<=plannedNodes.length,"Bounded marker population");
 if(percentage!==undefined)need(Number(percentage)===Math.floor(markers*100/plannedNodes.length),"Exact cumulative percentage");
 observations.push({line_number:i+1,marker_count:letters.length,cumulative_markers:markers,percentage:percentage===undefined?null:Number(percentage)});
}
need(ended&&groups.length===expected.length&&markers===plannedNodes.length,"Complete progress section");
for(let i=0;i<groups.length;i++)need(groups[i].markers.length===expected[i].nodes.length,"Exact per-file planned population");
const letters={};for(const group of groups)for(const char of group.markers)letters[char]=(letters[char]||0)+1;
const mapping={".":"passed","F":"failed","s":"skipped","x":"xfailed","X":"xpassed","E":"error"};
for(const[letter,name]of Object.entries(mapping)){const wanted=name==="error"?(status.summary_counts.error||0)+(status.summary_counts.errors||0):(status.summary_counts[name]||0);need((letters[letter]||0)===wanted,"Complete terminal marker/count reconciliation "+name);}
need(!status.unparsed_failure_lines.length,"All explicit failure lines parsed");
const failures={};for(const node of status.failed_nodes){const path=node.split("::")[0];failures[path]=(failures[path]||0)+1;}
for(const group of groups)need([...group.markers].filter(c=>c==="F").length===(failures[group.path]||0),"Per-file explicit failure reconciliation");
return {shard_index:index,job_id:status.job_id,plan_nodes:plannedNodes.length,groups:groups.map((g,i)=>({...g,planned_nodes:expected[i].nodes.length,all_markers_passed:g.markers.length>0&&/^\.+$/.test(g.markers)})),complete_file_path_order_and_population:true,complete_marker_total_and_percentage_checks:true,all_terminal_counts_and_failure_files_reconciled:true,marker_counts:letters,summary:status.summary,observations,scope:"Refinement from exact original per-file pytest progress and source-plan counts; individual mixed-status files remain unqualified."};
})
